//! Code generated by `gravenc` (the `graven-compiler` codegen, via `build.rs`) for the codegen's
//! edge cases. The real schemas (`bank`, `game`, `iot`, `stream`) are generated and tested
//! in `graven-schemas` itself; regressions in the generated text are caught by the
//! snapshots in `crates/graven-compiler/tests/snapshots`.
#![deny(unsafe_code)]

/// Codegen edge cases (`schemas/edge.graven`): required pointers, defaults of every type,
/// a scalar-only table nested and in a union, `[bool]`, `[enum]`, `[struct]`, a field name
/// that is a keyword, reserved fields.
pub mod edge {
    include!(concat!(env!("OUT_DIR"), "/edge.rs"));
}
/// Tricky names accepted by `check` (`schemas/names.graven`): prelude names (`Option`,
/// `FnOnce`, `String`), keywords as fields/variants (`r#type`) and a table whose layout
/// module is a keyword (`Type` ⇒ `mod r#type`). Compiling is enough.
/// (Lowercase variants like `r#loop` are on purpose; style lints are up to whoever
/// writes the schema.)
#[allow(nonstandard_style)]
pub mod names {
    include!(concat!(env!("OUT_DIR"), "/names.rs"));
}

/// Defaults at the extremes of every type (`schemas/defaults.graven`).
pub mod defaults {
    include!(concat!(env!("OUT_DIR"), "/defaults.rs"));
}

/// Shared types (`schemas/common.graven`), imported by [`orders`].
pub mod common {
    include!(concat!(env!("OUT_DIR"), "/common.rs"));
}

/// A schema that imports `common` (`schemas/orders.graven`): its accessors return the types of
/// [`common`] itself.
pub mod orders {
    include!(concat!(env!("OUT_DIR"), "/orders.rs"));
}
